#!/usr/bin/env node
/**
 * Prepare Revision Script (Global Manifest Approach)
 * 
 * Creates backup snapshots with unique UUID prefix.
 * Appends to global manifest.json in $TMPDIR/interactive-revision/.
 * User will edit original source files directly.
 * 
 * Usage: node prepare-revision.mjs --source <path1> --source <path2> ...
 * 
 * Output: JSON with snapshot mappings
 * 
 * Requires: Node.js >= 18.0.0
 */

import { access, mkdir, copyFile, writeFile, readFile } from 'fs/promises';
import { tmpdir } from 'os';
import { join, basename } from 'path';
import { randomUUID } from 'crypto';
import { parseArgs } from 'util';

const args = parseArgs({
  options: {
    source: { type: 'string', short: 's', multiple: true },
  },
  strict: true,
});

const sourcePaths = args.values.source || [];

if (sourcePaths.length === 0) {
  const result = {
    success: false,
    files: [],
    message: 'Missing required argument: --source <sourcePath> (specify at least one)',
  };
  console.log(JSON.stringify(result, null, 2));
  process.exit(1);
}

const baseDir = join(tmpdir(), 'interactive-revision');
const manifestPath = join(baseDir, 'manifest.json');

async function prepareRevision() {
  // Create base directory
  await mkdir(baseDir, { recursive: true });

  // Read existing manifest (if exists)
  let manifest;
  try {
    const manifestContent = await readFile(manifestPath, 'utf-8');
    manifest = JSON.parse(manifestContent);
  } catch {
    // No existing manifest, create new
    manifest = { files: [], createdAt: new Date().toISOString() };
  }

  // Process each source file
  const files = manifest.files || [];
  const addedFiles = [];  // Track files successfully added this call
  const errors = [];

  for (const sourcePath of sourcePaths) {
    // Check source exists
    try {
      await access(sourcePath);
    } catch {
      errors.push({
        sourcePath,
        message: `Source file does not exist: ${sourcePath}`,
      });
      continue;
    }

    // Check if already in manifest (avoid duplicate)
    const existingEntry = files.find(f => f.sourcePath === sourcePath);
    if (existingEntry) {
      errors.push({
        sourcePath,
        message: `File already in session: ${sourcePath}. Snapshot ID: ${existingEntry.snapshotId}`,
      });
      continue;
    }

    // Generate unique snapshot ID and path
    const snapshotId = randomUUID();
    const fileName = basename(sourcePath);
    const snapshotFileName = `${snapshotId}-${fileName}`;
    const snapshotPath = join(baseDir, snapshotFileName);

    // Copy backup
    try {
      await copyFile(sourcePath, snapshotPath);

      const newEntry = {
        sourcePath,
        snapshotPath,
        snapshotFileName,
        snapshotId,
        fileName,
      };
      files.push(newEntry);
      addedFiles.push(newEntry);  // Track as successfully added
    } catch (error) {
      const err = error instanceof Error ? error : new Error(String(error));
      errors.push({
        sourcePath,
        message: `Failed to create backup: ${err.message}`,
      });
    }
  }

  // Write manifest
  manifest.files = files;
  manifest.updatedAt = new Date().toISOString();

  try {
    await writeFile(manifestPath, JSON.stringify(manifest, null, 2));
  } catch (error) {
    const err = error instanceof Error ? error : new Error(String(error));
    errors.push({
      sourcePath: 'manifest',
      message: `Failed to write manifest: ${err.message}`,
    });
  }

  // Build result
  if (errors.length > 0 && files.length === 0) {
    const result = {
      success: false,
      files: [],
      errors,
      message: 'All files failed to prepare. See errors array for details.',
    };
    console.log(JSON.stringify(result, null, 2));
    process.exit(1);
  }

  // Show all files currently in session (not just new ones)
  const result = {
    success: true,
    baseDir,
    files: files,           // All files in session
    newFiles: addedFiles,   // Files successfully added this call
    errors: errors.length > 0 ? errors : undefined,
    message: `${addedFiles.length} file(s) added. Session now has ${files.length} file(s) total. User should edit the original source files directly. After edits, call: finalize-revision`,
  };

  console.log(JSON.stringify(result, null, 2));
}

prepareRevision();

import { test } from 'node:test';
import { strict as assert } from 'node:assert';
import { spawnSync } from 'node:child_process';
import { mkdtemp, rm, writeFile, readdir, access } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const scriptPath = join(__dirname, 'prepare-revision.mjs');

function runScript(args, env = {}) {
  return spawnSync('node', [scriptPath, ...args], {
    env: { ...process.env, ...env },
    encoding: 'utf-8',
  });
}

async function withTempDir(fn) {
  const tempDir = await mkdtemp(join(tmpdir(), 'ir-test-'));
  try {
    return await fn(tempDir);
  } finally {
    await rm(tempDir, { recursive: true, force: true });
  }
}

async function createSourceFile(dir, name, content = 'test content') {
  const filePath = join(dir, name);
  await writeFile(filePath, content);
  return filePath;
}


test('accepts --session-path argument for session isolation', async () => {
  await withTempDir(async (tempDir) => {
    const sourceFile = await createSourceFile(tempDir, 'source.txt');
    const result = runScript(
      ['--source', sourceFile, '--session-path', '/test/session/path'],
      { TMPDIR: tempDir }
    );

    assert.equal(result.status, 0, `Expected exit code 0, stderr: ${result.stderr}`);
    const output = JSON.parse(result.stdout);
    assert.equal(output.success, true);
  });
});

