import { test } from 'node:test';
import { strict as assert } from 'node:assert';
import { spawnSync } from 'node:child_process';
import { mkdtemp, rm, writeFile, readdir, access } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const scriptPath = join(__dirname, 'prepare-revision.mjs');

function runScript(args, env = {}) {
  return spawnSync('node', [scriptPath, ...args], {
    env: { ...process.env, ...env },
    encoding: 'utf-8',
  });
}

async function withTempDir(fn) {
  const tempDir = await mkdtemp(join(tmpdir(), 'ir-test-'));
  try {
    return await fn(tempDir);
  } finally {
    await rm(tempDir, { recursive: true, force: true });
  }
}

async function createSourceFile(dir, name, content = 'test content') {
  const filePath = join(dir, name);
  await writeFile(filePath, content);
  return filePath;
}


test('creates log file under $TMPDIR/interactive-revision/.logs/', async () => {
  await withTempDir(async (tempDir) => {
    const sourceFile = await createSourceFile(tempDir, 'source.txt');
    runScript(['--source', sourceFile], { TMPDIR: tempDir });

    const logFile = join(tempDir, 'interactive-revision', '.logs', 'interactive-revision.log');
    await access(logFile);
  });
});


test('different session paths create separate session directories', async () => {
  await withTempDir(async (tempDir) => {
    const sourceFile1 = await createSourceFile(tempDir, 'source1.txt', 'content1');
    const sourceFile2 = await createSourceFile(tempDir, 'source2.txt', 'content2');

    runScript(
      ['--source', sourceFile1, '--session-path', '/session/one'],
      { TMPDIR: tempDir }
    );
    runScript(
      ['--source', sourceFile2, '--session-path', '/session/two'],
      { TMPDIR: tempDir }
    );

    const entries = await readdir(join(tempDir, 'interactive-revision'));
    const sessionDirs = entries.filter(e => e !== '.logs');
    assert.ok(
      sessionDirs.length >= 2,
      `Expected at least 2 session directories, got: ${JSON.stringify(sessionDirs)}`
    );
  });
});


test('same session path reuses the same session directory', async () => {
  await withTempDir(async (tempDir) => {
    const sourceFile1 = await createSourceFile(tempDir, 'source1.txt', 'content1');
    const sourceFile2 = await createSourceFile(tempDir, 'source2.txt', 'content2');

    runScript(
      ['--source', sourceFile1, '--session-path', '/same/path'],
      { TMPDIR: tempDir }
    );
    runScript(
      ['--source', sourceFile2, '--session-path', '/same/path'],
      { TMPDIR: tempDir }
    );

    const entries = await readdir(join(tempDir, 'interactive-revision'));
    const sessionDirs = entries.filter(e => e !== '.logs');
    assert.equal(
      sessionDirs.length,
      1,
      `Expected exactly 1 session directory, got: ${JSON.stringify(sessionDirs)}`
    );
  });
});


test('basic backup works without --session-path (existing behavior)', async () => {
  await withTempDir(async (tempDir) => {
    const sourceFile = await createSourceFile(tempDir, 'source.txt', 'original content');
    const result = runScript(['--source', sourceFile], { TMPDIR: tempDir });

    assert.equal(result.status, 0, `Expected exit code 0, stderr: ${result.stderr}`);
    const output = JSON.parse(result.stdout);
    assert.equal(output.success, true);

    // Verify something was created under interactive-revision
    const entries = await readdir(join(tempDir, 'interactive-revision'));
    assert.ok(entries.length > 0, 'Expected files under interactive-revision directory');
  });
});
